import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  Fragment,
  h,
  Host,
  Listen,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import { Breakpoint } from '../../../types';
import { AriaAttributes, extractAriaAttributes } from '../../../utils/a11y-helper';
import { breakpointMapping } from '../../../utils/breakpoint-mapping';
import { createMenuObserver, handleActiveMenuAttributes, observeAllMenus } from '../../../utils/menu-helper';

type ItemElement =
  | HTMLGroupuiGlobalTopNavigationItemElement
  | HTMLGroupuiGlobalTopNavigationUtilityItemElement
  | HTMLGroupuiGlobalTopNavigationMobileItemElement
  | HTMLGroupuiGlobalTopNavigationMobileUtilityItemElement;

/**
 * @slot default - default slot for the navigation items
 */
@Component({
  tag: 'groupui-global-top-navigation',
  styleUrl: 'global-top-navigation.scss',
  shadow: true,
})
export class GlobalTopNavigation implements ComponentInterface {
  /**
   * Breakpoint on which the layout switches to mobile.
   */
  @Prop({ reflect: true }) readonly breakpoint: Breakpoint = 'l';

  /**
   * Custom breakpoint in pixels to switch to mobile layout.
   * Overwrites the `breakpoint` property.
   */
  @Prop({ reflect: true }) readonly customBreakpoint: number;

  /**
   * Deactivates the active state management.
   */
  @Prop({ reflect: true }) readonly manualMode: boolean = false;

  /**
   * Emitted when the component has loaded.
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * Emitted when the active item changes
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  @State() private itemElements: ItemElement[] = [];

  @State() private activeItemIndex: number = -1;
  @State() private ariaAttributes: AriaAttributes;

  @State() isMobileLayoutVisible: boolean;

  @Element() host: HTMLElement;

  private resizeObserver: ResizeObserver;
  private menuObserver: MutationObserver;

  connectedCallback() {
    if (this.resizeObserver) {
      this.observeResize();
    }
    if (this.menuObserver) {
      handleActiveMenuAttributes(this.host, this.menuObserver);
    }
  }

  componentWillLoad(): void {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this?.updateItems();
    this?.assignBrandLogoIfPresent();
    this.resizeObserver = this.createResizeObserver();
    this.observeResize();
    this.updateManualModeOfBurger();
    this.menuObserver = createMenuObserver();
    handleActiveMenuAttributes(this.host, this.menuObserver);
  }

  componentDidLoad() {
    this.updateSlotChangeEventListener();
    this.groupuiDidLoad.emit();
  }

  disconnectedCallback() {
    this.resizeObserver?.disconnect();
    this.menuObserver?.disconnect();
  }

  @Watch('manualMode')
  updateManualModeOfBurger() {
    this.host.querySelectorAll('groupui-burger-menu').forEach((burger) => {
      if (this.manualMode) {
        burger.setAttribute('manual-mode', '');
      } else {
        burger.removeAttribute('manual-mode');
      }
    });
  }

  private createResizeObserver() {
    return new ResizeObserver((element) => {
      const breakpoint = this.customBreakpoint ?? breakpointMapping.get(this.breakpoint);
      this.isMobileLayoutVisible = element[0].contentRect.width < breakpoint;
    });
  }

  private observeResize() {
    this.resizeObserver?.observe(window.document.documentElement);
  }

  private updateItems(): void {
    this.updateSlotChangeEventListener();
    let navItems: HTMLGroupuiGlobalTopNavigationItemElement[] | HTMLGroupuiGlobalTopNavigationMobileItemElement[];
    let utilityItems:
      | HTMLGroupuiGlobalTopNavigationUtilityItemElement[]
      | HTMLGroupuiGlobalTopNavigationMobileUtilityItemElement[];

    if (this.isMobileLayoutVisible) {
      navItems = Array.from(this.host.querySelectorAll('groupui-global-top-navigation-mobile-item'));
      utilityItems = Array.from(this.host.querySelectorAll('groupui-global-top-navigation-mobile-utility-item'));
    } else {
      navItems = Array.from(this.host.querySelectorAll('groupui-global-top-navigation-item'));
      utilityItems = Array.from(this.host.querySelectorAll('groupui-global-top-navigation-utility-item'));
    }

    this.itemElements = [...navItems, ...utilityItems];
    this.removeItemsInsidePopovers();
    this.removeItemsInsideMenus();

    if (!this.manualMode) {
      const initialActiveIndex = this.itemElements.findIndex((item) => item.hasAttribute('active'));
      if (initialActiveIndex >= 0) {
        this.setActiveItem(initialActiveIndex);
      }
    }
  }

  private removeItemsInsidePopovers() {
    this.itemElements = this.itemElements.filter((item) => item.querySelector('[slot="popover"]') == null);
  }

  private removeItemsInsideMenus() {
    this.itemElements = this.itemElements.filter((item) => !item.closest('groupui-menu'));
  }

  private setActiveItem(index: number): void {
    if (index === this.activeItemIndex) return;
    this.itemElements.forEach((el) => el.removeAttribute('active'));

    if (index >= 0 && index < this.itemElements.length) {
      this.itemElements[index].setAttribute('active', '');
      this.activeItemIndex = index;
    } else {
      this.activeItemIndex = -1;
    }
  }

  @Listen('click')
  handleClick(event: Event): void {
    const target =
      (event.target as HTMLElement).closest(
        'groupui-global-top-navigation-item, groupui-global-top-navigation-mobile-item'
      ) ||
      (event.target as HTMLElement).closest(
        'groupui-global-top-navigation-utility-item, groupui-global-top-navigation-mobile-utility-item'
      );

    if (!target || this.manualMode) {
      return;
    }

    const clickedItemIndex = this.itemElements.indexOf(target as ItemElement);
    if (clickedItemIndex >= 0) {
      this.setActiveItem(clickedItemIndex);
      this.groupuiChange.emit();
      this.host.dispatchEvent(new window.Event('change'));
    }
  }

  private updateSlotChangeEventListener() {
    [
      'groupui-global-top-navigation-items',
      'groupui-global-top-navigation-utility-items',
      'groupui-global-top-navigation-mobile-items',
      'groupui-global-top-navigation-mobile-utility-items',
    ].forEach((tag) => {
      this.host.querySelector(tag)?.removeEventListener('groupuiSlotchange', (e) => this.handleSlotChange(e));
      this.host.querySelector(tag)?.addEventListener('groupuiSlotchange', (e) => this.handleSlotChange(e));
    });
  }

  private handleSlotChange = (e: Event): void => {
    e.stopPropagation();
    this.updateItems();
    this.assignBrandLogoIfPresent();
    observeAllMenus(this.host, this.menuObserver);
  };

  private assignBrandLogoIfPresent(): void {
    const logo = this.host.querySelector('groupui-brand-logo');
    if (!logo) {
      return;
    }
    logo.setAttribute('slot', 'brand-logo');
  }

  private hasUtilityItems(): boolean {
    return this.host.querySelectorAll('groupui-global-top-navigation-utility-item').length > 0;
  }

  private hasMobileUtilityItems(): boolean {
    return this.host.querySelectorAll('groupui-global-top-navigation-mobile-utility-item').length > 0;
  }

  private hasNavItems(): boolean {
    return this.host.querySelectorAll('groupui-global-top-navigation-item').length > 0;
  }

  private hasMobileNavItems(): boolean {
    return this.host.querySelectorAll('groupui-global-top-navigation-mobile-item').length > 0;
  }

  render() {
    const hasUtilityItems = this.hasUtilityItems();
    const hasNavItems = this.hasNavItems();

    const hasMobileUtilityItems = this.hasMobileUtilityItems();
    const hasMobileNavItems = this.hasMobileNavItems();
    return (
      <Host>
        <nav {...this.ariaAttributes}>
          <slot name="brand-logo"></slot>
          {!this.isMobileLayoutVisible && (
            <Fragment>
              <slot name="nav-items"></slot>
              {hasUtilityItems && hasNavItems && <groupui-divider inverted vertical slot="divider"></groupui-divider>}
              <slot name="utility-items"></slot>
            </Fragment>
          )}
          {this.isMobileLayoutVisible && (
            <Fragment>
              <slot name="mobile-nav-items"></slot>
              {hasMobileUtilityItems && hasMobileNavItems && (
                <groupui-divider inverted vertical slot="divider"></groupui-divider>
              )}
              <slot name="mobile-utility-items"></slot>
            </Fragment>
          )}
        </nav>
      </Host>
    );
  }
}
